// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Liveness probe.
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// Revoke a pending invitation. Returns 204.
	// (DELETE /v1/invitations/{invitation_id})
	RevokeInvitation(ctx context.Context, request RevokeInvitationRequestObject) (RevokeInvitationResponseObject, error)
	// Fetch an invitation by id. Plaintext token never echoed.
	// (GET /v1/invitations/{invitation_id})
	GetInvitation(ctx context.Context, request GetInvitationRequestObject) (GetInvitationResponseObject, error)
	// Accept a pending invitation. Creates the Member row.
	// (POST /v1/invitations/{invitation_id}/accept)
	AcceptInvitation(ctx context.Context, request AcceptInvitationRequestObject) (AcceptInvitationResponseObject, error)
	// List BYOK notification channels in the caller's tenant.
	// (GET /v1/notification-channels)
	ListNotificationChannels(ctx context.Context, request ListNotificationChannelsRequestObject) (ListNotificationChannelsResponseObject, error)
	// Create a BYOK notification channel.
	// (POST /v1/notification-channels)
	CreateNotificationChannel(ctx context.Context, request CreateNotificationChannelRequestObject) (CreateNotificationChannelResponseObject, error)
	// Soft-delete a notification channel.
	// (DELETE /v1/notification-channels/{channel_id})
	DeleteNotificationChannel(ctx context.Context, request DeleteNotificationChannelRequestObject) (DeleteNotificationChannelResponseObject, error)
	// Fetch a notification channel by id.
	// (GET /v1/notification-channels/{channel_id})
	GetNotificationChannel(ctx context.Context, request GetNotificationChannelRequestObject) (GetNotificationChannelResponseObject, error)
	// Update a notification channel (metadata only).
	// (PATCH /v1/notification-channels/{channel_id})
	UpdateNotificationChannel(ctx context.Context, request UpdateNotificationChannelRequestObject) (UpdateNotificationChannelResponseObject, error)
	// Rotate a channel's BYOK credentials.
	// (POST /v1/notification-channels/{channel_id}/rotate-credentials)
	RotateNotificationChannelCredentials(ctx context.Context, request RotateNotificationChannelCredentialsRequestObject) (RotateNotificationChannelCredentialsResponseObject, error)
	// List registered notification workflows for the caller's tenant.
	// (GET /v1/notification-workflows)
	ListNotificationWorkflows(ctx context.Context, request ListNotificationWorkflowsRequestObject) (ListNotificationWorkflowsResponseObject, error)
	// Register a (name → Novu workflow id) mapping.
	// (POST /v1/notification-workflows)
	RegisterNotificationWorkflow(ctx context.Context, request RegisterNotificationWorkflowRequestObject) (RegisterNotificationWorkflowResponseObject, error)
	// Update the Novu workflow id and/or description for a registered workflow.
	// (PATCH /v1/notification-workflows/{workflow_id})
	UpdateNotificationWorkflow(ctx context.Context, request UpdateNotificationWorkflowRequestObject) (UpdateNotificationWorkflowResponseObject, error)
	// List notifications in the caller's tenant.
	// (GET /v1/notifications)
	ListNotifications(ctx context.Context, request ListNotificationsRequestObject) (ListNotificationsResponseObject, error)
	// Queue a notification for delivery via Novu.
	// (POST /v1/notifications/send)
	SendNotification(ctx context.Context, request SendNotificationRequestObject) (SendNotificationResponseObject, error)
	// Fetch a notification by id.
	// (GET /v1/notifications/{notification_id})
	GetNotification(ctx context.Context, request GetNotificationRequestObject) (GetNotificationResponseObject, error)
	// Soft-delete an organization. Refuses while active members remain.
	// (DELETE /v1/organizations/{organization_id})
	DeleteOrganization(ctx context.Context, request DeleteOrganizationRequestObject) (DeleteOrganizationResponseObject, error)
	// Fetch an organization by id.
	// (GET /v1/organizations/{organization_id})
	GetOrganization(ctx context.Context, request GetOrganizationRequestObject) (GetOrganizationResponseObject, error)
	// Update an organization.
	// (PATCH /v1/organizations/{organization_id})
	UpdateOrganization(ctx context.Context, request UpdateOrganizationRequestObject) (UpdateOrganizationResponseObject, error)
	// List invitations for an organization.
	// (GET /v1/organizations/{organization_id}/invitations)
	ListInvitations(ctx context.Context, request ListInvitationsRequestObject) (ListInvitationsResponseObject, error)
	// Create an invitation. Email is queued; plaintext token returned ONCE.
	// (POST /v1/organizations/{organization_id}/invitations)
	CreateInvitation(ctx context.Context, request CreateInvitationRequestObject) (CreateInvitationResponseObject, error)
	// List members of an organization.
	// (GET /v1/organizations/{organization_id}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// Remove a member (soft-delete; status='removed').
	// (DELETE /v1/organizations/{organization_id}/members/{member_id})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)
	// Fetch a member by id.
	// (GET /v1/organizations/{organization_id}/members/{member_id})
	GetMember(ctx context.Context, request GetMemberRequestObject) (GetMemberResponseObject, error)
	// Update a member's role assignment (Phase 8 RBAC placeholder).
	// (PATCH /v1/organizations/{organization_id}/members/{member_id})
	UpdateMember(ctx context.Context, request UpdateMemberRequestObject) (UpdateMemberResponseObject, error)
	// List tenants visible to the caller's Deployment.
	// (GET /v1/tenants)
	ListTenants(ctx context.Context, request ListTenantsRequestObject) (ListTenantsResponseObject, error)
	// Create a tenant. Auto-creates a default Organization.
	// (POST /v1/tenants)
	CreateTenant(ctx context.Context, request CreateTenantRequestObject) (CreateTenantResponseObject, error)
	// Soft-delete a tenant. Retention applies before physical purge.
	// (DELETE /v1/tenants/{tenant_id})
	DeleteTenant(ctx context.Context, request DeleteTenantRequestObject) (DeleteTenantResponseObject, error)
	// Fetch a tenant by id.
	// (GET /v1/tenants/{tenant_id})
	GetTenant(ctx context.Context, request GetTenantRequestObject) (GetTenantResponseObject, error)
	// Update a tenant. Idempotent. ETag concurrency control required.
	// (PATCH /v1/tenants/{tenant_id})
	UpdateTenant(ctx context.Context, request UpdateTenantRequestObject) (UpdateTenantResponseObject, error)
	// List organizations in a tenant.
	// (GET /v1/tenants/{tenant_id}/organizations)
	ListOrganizations(ctx context.Context, request ListOrganizationsRequestObject) (ListOrganizationsResponseObject, error)
	// Create a new organization in a tenant (multi_org required).
	// (POST /v1/tenants/{tenant_id}/organizations)
	CreateOrganization(ctx context.Context, request CreateOrganizationRequestObject) (CreateOrganizationResponseObject, error)
	// List users in the caller's tenant.
	// (GET /v1/users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// Create a platform user. Mirrors the row into Keycloak.
	// (POST /v1/users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)
	// Soft-delete a platform user. Disables the Keycloak user.
	// (DELETE /v1/users/{user_id})
	DeleteUser(ctx context.Context, request DeleteUserRequestObject) (DeleteUserResponseObject, error)
	// Fetch a platform user by id.
	// (GET /v1/users/{user_id})
	GetUser(ctx context.Context, request GetUserRequestObject) (GetUserResponseObject, error)
	// Update a platform user. ETag concurrency control required.
	// (PATCH /v1/users/{user_id})
	UpdateUser(ctx context.Context, request UpdateUserRequestObject) (UpdateUserResponseObject, error)
	// Disable a platform user. Emits user.disabled.
	// (POST /v1/users/{user_id}/disable)
	DisableUser(ctx context.Context, request DisableUserRequestObject) (DisableUserResponseObject, error)
	// Enable a previously-disabled platform user.
	// (POST /v1/users/{user_id}/enable)
	EnableUser(ctx context.Context, request EnableUserRequestObject) (EnableUserResponseObject, error)
	// Trigger a password-reset email via Keycloak.
	// (POST /v1/users/{user_id}/reset-password)
	TriggerPasswordReset(ctx context.Context, request TriggerPasswordResetRequestObject) (TriggerPasswordResetResponseObject, error)
	// List linked social providers for a user.
	// (GET /v1/users/{user_id}/social-providers)
	ListSocialProviders(ctx context.Context, request ListSocialProvidersRequestObject) (ListSocialProvidersResponseObject, error)
	// Start a social-provider link flow. Returns the Keycloak link URL.
	// (POST /v1/users/{user_id}/social-providers)
	LinkSocialProvider(ctx context.Context, request LinkSocialProviderRequestObject) (LinkSocialProviderResponseObject, error)
	// Unlink a social provider. Emits user.social_unlinked.
	// (DELETE /v1/users/{user_id}/social-providers/{provider})
	UnlinkSocialProvider(ctx context.Context, request UnlinkSocialProviderRequestObject) (UnlinkSocialProviderResponseObject, error)
	// Trigger an email-verification action via Keycloak.
	// (POST /v1/users/{user_id}/verify-email)
	TriggerEmailVerify(ctx context.Context, request TriggerEmailVerifyRequestObject) (TriggerEmailVerifyResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

